"use client";

import { useEffect, useRef } from "react";

declare global {
  interface Window {
    /* Posé quand l'ouverture est finie (ou déjà vue) : les timelines
       d'entrée des sections lisent ce drapeau pour caler leur delay. */
    __prismLoaded?: boolean;
  }
}

/*
 * Ouverture — le rideau d'atelier (D30, run 2).
 * Sur l'ivoire du studio (grain 2 octaves, halo aurore), le
 * monogramme ΛV se dessine au trait puis s'extrude en verre — la
 * nappe glacée monte dans le tracé, l'ombre portée s'épaissit, une
 * lame de lumière balaie — pendant qu'un compteur mono suit la
 * VRAIE progression de chargement : DOM 20 %, polices 25 %,
 * poster du hero 25 %, préparation des textures de la scène 30 %
 * (jusqu'à 30 % de sa peinture — le seuil où le poster couvre le
 * canvas ; événements « neva:progress » émis par GlassSculpture).
 * À cache chaud tout est prêt ≤ 1,8 s ; sur réseau lent le
 * compteur reflète la réalité — jamais une fausse barre. Sortie
 * par fondu de cache (l'ivoire du veil = l'ivoire de la page).
 * Le grand loader joue une fois par session. Les F5 et arrivées
 * directes suivants reçoivent le MICRO-RIDEAU (LOT 2 §2) : le
 * même ivoire (halo + grain, sans monogramme ni compteur — un
 * script inline le masque avant le premier paint) tenu jusqu'aux
 * mêmes conditions « net », puis fondu 320 ms — c'est lui qui tue
 * le « F5 flou ». Les navigations internes n'ont aucun rideau.
 * Purement décoratif : aucun état React, DOM piloté en temps
 * absolu f(t) — aucune branche reduced-motion (preuve 0 diff).
 */
const DRAW_MS = 620; /* le trait se dessine */
const FILL_MS = 560; /* le verre monte, la lame balaie */
const EXIT_MS = 450; /* fondu du cache */
const MICRO_EXIT_MS = 320; /* fondu du micro-rideau (250-400 exigés) */
const MIN_SHOW_MS = DRAW_MS + FILL_MS; /* jamais de sortie avant l'extrusion */
const SWEEP_PERIOD_MS = 2400; /* en attente réelle, la lame repasse */

/* Vrai jusqu'au premier montage du module : distingue le chargement
   de document (F5, arrivée directe — le micro-rideau s'applique) de
   la navigation interne (remontage de la home : la préparation de
   scène, singleton résolu, ne ré-émettrait pas sa progression — le
   rideau attendrait son filet pour rien). */
let documentBoot = true;

/* le grain de l'atelier — le MÊME motif 2 octaves que les fonds
   de scène (.pv-scene::after), fréquence 0,8, 256 px */
const GRAIN_URI =
  "url(\"data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.8' numOctaves='2' stitchTiles='stitch'/%3E%3CfeColorMatrix type='saturate' values='0'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)'/%3E%3C/svg%3E\")";

export default function PrismLoader() {
  const veilRef = useRef<HTMLDivElement>(null);
  const coreRef = useRef<HTMLDivElement>(null);
  const strokeRef = useRef<SVGGElement>(null);
  const fillRef = useRef<SVGGElement>(null);
  const sheenRef = useRef<SVGRectElement>(null);
  const shadowRef = useRef<SVGEllipseElement>(null);
  const countRef = useRef<HTMLSpanElement>(null);

  useEffect(() => {
    const veil = veilRef.current;
    if (!veil) return;

    const isDocumentLoad = documentBoot;
    documentBoot = false;

    let seen = false;
    try {
      seen = window.sessionStorage.getItem("prism-overture") !== null;
    } catch {
      /* stockage indisponible : on rejoue l'ouverture complète */
    }

    if (seen && !isDocumentLoad) {
      /* navigation interne : la page est déjà là, aucun rideau */
      window.__prismLoaded = true;
      veil.style.display = "none";
      return;
    }

    /* QA 20/08 : React prend la main — le script inline du compteur
       (pré-hydratation) lit ce drapeau et s'arrête. */
    veil.dataset.jsLive = "1";

    /* ── la vraie progression ─────────────────────────────────── */
    const marks = { dom: 0, fonts: 0, poster: 0, scene: 0, canvas: 0 };
    const cleanups: (() => void)[] = [];

    if (document.readyState !== "loading") {
      marks.dom = 1;
    } else {
      const onDom = () => {
        marks.dom = 1;
      };
      document.addEventListener("DOMContentLoaded", onDom, { once: true });
      cleanups.push(() => document.removeEventListener("DOMContentLoaded", onDom));
    }

    if (document.fonts?.ready) {
      document.fonts.ready.then(() => {
        marks.fonts = 1;
      });
    } else {
      marks.fonts = 1;
    }

    /* run 3, LOT 6 : « load » ne suffit pas — l'image peut être
       chargée mais pas DÉCODÉE au moment de la levée (une frame
       floue/blanche possible). decode() garantit des pixels prêts ;
       error/absence libèrent la marque (jamais d'otage). */
    const posterImg = document.querySelector<HTMLImageElement>(
      "#top picture img"
    );
    if (!posterImg) {
      marks.poster = 1;
    } else {
      const markDecoded = () => {
        posterImg
          .decode()
          .catch(() => {
            /* décodage refusé (source retirée…) : on libère */
          })
          .finally(() => {
            marks.poster = 1;
          });
      };
      if (posterImg.complete && posterImg.naturalWidth > 0) {
        markDecoded();
      } else {
        const onPoster = () => markDecoded();
        const onError = () => {
          marks.poster = 1;
        };
        posterImg.addEventListener("load", onPoster, { once: true });
        posterImg.addEventListener("error", onError, { once: true });
        cleanups.push(() => {
          posterImg.removeEventListener("load", onPoster);
          posterImg.removeEventListener("error", onError);
        });
      }
    }

    const onScene = (e: Event) => {
      const detail = (e as CustomEvent<{ p?: number; phase?: string }>).detail;
      const p = detail?.p ?? 0;
      if (p > marks.scene) marks.scene = p;
      /* retour client (run 3 bis) : la scène est « prête » quand le
         CANVAS l'est (compile faite, fondu enclenché) — le
         micro-rideau du F5 tient jusque-là, plus jamais de hero en
         cours d'apparition à la levée */
      if (detail?.phase === "canvas" && p >= 1) marks.canvas = 1;
    };
    window.addEventListener("neva:progress", onScene);
    cleanups.push(() => window.removeEventListener("neva:progress", onScene));
    /* filet : si la scène n'émet jamais (WebGL absent, page sans
       hero), sa part se libère après 2,6 s — le loader ne retient
       jamais l'utilisateur en otage d'un canvas mort */
    const sceneFallback = window.setTimeout(() => {
      marks.scene = Math.max(marks.scene, 0.22);
    }, 2600);
    cleanups.push(() => window.clearTimeout(sceneFallback));

    /* seuil scène 22 % : le poster couvre le canvas bien au-delà —
       à cache chaud, p atteint 100 vers 1,4-1,6 s (sortie ≤ 1,8 s) */
    const realProgress = () =>
      marks.dom * 0.2 +
      marks.fonts * 0.25 +
      marks.poster * 0.25 +
      Math.min(marks.scene / 0.22, 1) * 0.3;

    /* ── micro-rideau (LOT 2 §2) — F5 et arrivées directes ──────
       Pas de chorégraphie : l'ivoire (halo + grain) tient jusqu'aux
       MÊMES conditions « net » que l'ouverture, puis fond. Derrière
       lui, le poster net (≤ 60 Ko) couvre l'arrivée du canvas. */
    if (seen) {
      /* ceinture — le script inline de la page masque déjà la pièce
         centrale avant le premier paint */
      if (coreRef.current) coreRef.current.style.display = "none";
      /* filet canvas : WebGL absent ou boot lent (mesuré 14 s à
         CPU ×6 en MID) — au-delà de 4 s le poster net prime, le
         canvas arrivera en fondu ; le rideau ne retient jamais plus */
      const canvasFallback = window.setTimeout(() => {
        marks.canvas = 1;
      }, 4000);
      cleanups.push(() => window.clearTimeout(canvasFallback));
      let microRaf = 0;
      let microLeave = 0;
      const wait = () => {
        if (realProgress() < 1 || marks.canvas < 1) {
          microRaf = requestAnimationFrame(wait);
          return;
        }
        window.__prismLoaded = true;
        veil.style.transition = `opacity ${MICRO_EXIT_MS}ms cubic-bezier(0.65,0,0.35,1)`;
        veil.style.opacity = "0";
        veil.style.pointerEvents = "none";
        microLeave = window.setTimeout(() => {
          veil.style.display = "none";
        }, MICRO_EXIT_MS + 60);
      };
      microRaf = requestAnimationFrame(wait);
      return () => {
        cancelAnimationFrame(microRaf);
        window.clearTimeout(microLeave);
        cleanups.forEach((fn) => fn());
      };
    }

    /* ── la chorégraphie f(t) + le compteur réel ────────────────
       QA 20/08 : t0 = navigationStart (temps ABSOLU), plus l'instant
       d'hydratation — en réseau lent, l'hydratation arrivait à ~8 s
       et le rideau restait un écran mort (compteur à 000, monogramme
       jamais dessiné) pendant tout le téléchargement. Le trait et
       l'extrusion jouent désormais en CSS dès le premier paint
       (.pv-overture-*, globals.css) ; le JS reprend ici la MÊME
       f(t) absolue (continuité au pixel) et coupe les animations
       CSS. Le compteur repart de la valeur affichée par le script
       inline — il ne recule jamais. */
    const t0 = 0;
    let raf = 0;
    let leaveTimer = 0;
    let shown = Number(countRef.current?.textContent?.slice(0, 3)) || 0;
    let leaving = false;
    const easeOut = (p: number) => 1 - Math.pow(1 - p, 3);

    for (const ref of [strokeRef, fillRef, sheenRef, shadowRef]) {
      if (ref.current) (ref.current as SVGElement).style.animation = "none";
    }

    /* l'ouverture ne se lève plus AVANT le canvas (le poster figé
       « zoomé/flou » perçu au calibrage) — même filet 4 s que le
       micro-rideau : jamais l'utilisateur en otage. */
    const ouvertureCanvasFallback = window.setTimeout(() => {
      marks.canvas = 1;
    }, 4000);
    cleanups.push(() => window.clearTimeout(ouvertureCanvasFallback));

    const tick = (t: number) => {
      const el = t - t0;
      /* compteur : approche exponentielle de la progression RÉELLE
         (rattrapage ~220 ms — des incréments doux, pas de sauts) */
      const target = realProgress() * 100;
      shown = Math.max(shown, shown + (target - shown) * 0.22);
      if (countRef.current)
        countRef.current.textContent = `${String(Math.min(100, Math.round(shown))).padStart(3, "0")} — 100`;
      /* phase 1 : le trait se dessine */
      const pd = easeOut(Math.min(el / DRAW_MS, 1));
      if (strokeRef.current)
        strokeRef.current.style.strokeDashoffset = String(1 - pd);
      /* phase 2 : l'extrusion — le verre monte dans le tracé,
         l'ombre portée s'épaissit sous la pièce */
      const pf = easeOut(Math.min(Math.max((el - DRAW_MS) / FILL_MS, 0), 1));
      if (fillRef.current) fillRef.current.style.opacity = String(pf);
      if (shadowRef.current) {
        shadowRef.current.style.opacity = String(0.16 * pf);
        shadowRef.current.setAttribute("rx", String(560 + 140 * pf));
      }
      /* la lame : un balayage pendant l'extrusion, puis — si le
         chargement réel se prolonge — elle repasse (période fixe,
         fonction absolue du temps) */
      if (sheenRef.current) {
        let sx = -560;
        if (el <= DRAW_MS + FILL_MS) {
          sx = -560 + pf * 2560;
        } else {
          const loop = ((el - DRAW_MS - FILL_MS) % SWEEP_PERIOD_MS) / SWEEP_PERIOD_MS;
          sx = loop < 0.42 ? -560 + easeOut(loop / 0.42) * 2560 : 2000;
        }
        sheenRef.current.setAttribute("x", String(sx));
      }

      const done = realProgress() >= 1 && el >= MIN_SHOW_MS && marks.canvas >= 1;
      if (!done) {
        raf = requestAnimationFrame(tick);
      } else if (!leaving) {
        leaving = true;
        if (countRef.current) countRef.current.textContent = "100 — 100";
        window.sessionStorage.setItem("prism-overture", "1");
        window.__prismLoaded = true;
        /* sortie : le cache s'éteint en fondu — l'ivoire du veil
           EST l'ivoire de la page, la scène est déjà derrière */
        veil.style.transition = `opacity ${EXIT_MS}ms cubic-bezier(0.65,0,0.35,1)`;
        veil.style.opacity = "0";
        veil.style.pointerEvents = "none";
        leaveTimer = window.setTimeout(() => {
          veil.style.display = "none";
        }, EXIT_MS + 60);
      }
    };
    raf = requestAnimationFrame(tick);
    return () => {
      cancelAnimationFrame(raf);
      window.clearTimeout(leaveTimer);
      cleanups.forEach((fn) => fn());
    };
  }, []);

  return (
    <div
      ref={veilRef}
      aria-hidden
      data-prism-veil
      className="fixed inset-0 z-[120] flex items-center justify-center bg-[#060606]"
    >
      {/* le halo de l'atelier respire déjà derrière le monogramme */}
      <div
        className="pointer-events-none absolute inset-0"
        style={{
          background:
            "radial-gradient(30% 38% at 40% 34%, rgba(184,161,232,0.16) 0%, rgba(184,161,232,0) 70%), radial-gradient(26% 34% at 60% 62%, rgba(240,197,168,0.15) 0%, rgba(240,197,168,0) 72%)",
        }}
      />
      {/* le grain de l'atelier — 2 octaves, comme chaque scène */}
      <div
        className="pointer-events-none absolute inset-0"
        style={{
          backgroundImage: GRAIN_URI,
          backgroundSize: "256px 256px",
          opacity: 0.035,
          mixBlendMode: "screen",
        }}
      />
      <div
        ref={coreRef}
        className="pv-overture-core relative flex w-[240px] flex-col items-center gap-7"
      >
        <svg viewBox="0 0 1441 1120" className="w-[120px]">
          <defs>
            <linearGradient id="pvGlassFill" x1="0" y1="0" x2="1" y2="1">
              <stop offset="0%" stopColor="rgba(184,161,232,0.28)" />
              <stop offset="55%" stopColor="rgba(246,243,238,0.30)" />
              <stop offset="100%" stopColor="rgba(240,197,168,0.30)" />
            </linearGradient>
            <clipPath id="pvMonoClip">
              <path d="M440.2 0 L864.6 1000 L694.6 1000 L441 379 L180.1 1000 L0 1000 Z" />
              <path d="M439.5 710 L559.2 1000 L320 1000 Z" />
              <path d="M575 0 L755.1 0 L1013 618 L1266.6 0 L1438.1 0 L1015.2 990 Z" />
              <path d="M893.4 0 L1134.1 0 L1013.7 292 Z" />
            </clipPath>
          </defs>
          {/* l'ombre portée de l'extrusion — la pièce se pose.
              Les classes pv-overture-* jouent la MÊME chorégraphie
              en CSS pur dès le premier paint (QA 20/08) : sur
              réseau lent le rideau vit avant l'hydratation ; le JS
              coupe ces animations quand il reprend f(t). */}
          <ellipse
            ref={shadowRef}
            className="pv-overture-shadow"
            cx="720"
            cy="1078"
            rx="560"
            ry="26"
            fill="rgba(0,0,0,1)"
            style={{ opacity: 0, filter: "blur(14px)" }}
          />
          {/* le verre — monte dans le tracé, avec sa lame */}
          <g ref={fillRef} className="pv-overture-fill" style={{ opacity: 0 }}>
            <g clipPath="url(#pvMonoClip)">
              <rect width="1441" height="1000" fill="url(#pvGlassFill)" />
              <rect
                ref={sheenRef}
                x="-560"
                y="-60"
                width="360"
                height="1120"
                fill="rgba(255,255,255,0.55)"
                transform="skewX(-14)"
              />
            </g>
          </g>
          {/* le trait — se dessine en premier */}
          <g
            ref={strokeRef}
            className="pv-overture-stroke"
            fill="none"
            stroke="#F2F2F0"
            strokeWidth="7"
            pathLength={1}
            strokeDasharray="1"
            style={{ strokeDashoffset: 1 }}
          >
            <path pathLength={1} d="M440.2 0 L864.6 1000 L694.6 1000 L441 379 L180.1 1000 L0 1000 Z" />
            <path pathLength={1} d="M439.5 710 L559.2 1000 L320 1000 Z" />
            <path pathLength={1} d="M575 0 L755.1 0 L1013 618 L1266.6 0 L1438.1 0 L1015.2 990 Z" />
            <path pathLength={1} d="M893.4 0 L1134.1 0 L1013.7 292 Z" />
          </g>
        </svg>
        <span
          ref={countRef}
          id="pv-ouverture-count"
          /* le script inline ci-dessous écrit dans ce span AVANT
             l'hydratation : sans ce drapeau, React régénère l'arbre
             (mismatch SSR) et le rideau clignote */
          suppressHydrationWarning
          className="font-mono text-[10px] tracking-[0.3em] text-mist"
        >
          000 — 100
        </span>
        {/* Compteur pré-hydratation (QA 20/08) : exécuté au parse
            HTML, il suit le VRAI téléchargement (resource timings +
            DOM) et monte jusqu'à 60 % — la part « réseau » de la
            pondération. React reprend depuis la valeur affichée
            (data-js-live) ; les sessions vues (micro-rideau) ne
            l'exécutent pas. */}
        <script
          dangerouslySetInnerHTML={{
            __html: `(function(){try{
if(document.documentElement.dataset.prismSeen)return;
var v=document.currentScript&&document.currentScript.closest('[data-prism-veil]');
var c=document.getElementById('pv-ouverture-count');
if(!v||!c)return;
var s=0;
function f(){
if(v.dataset.jsLive==='1'||v.style.display==='none')return;
var r=performance.getEntriesByType('resource'),d=0;
for(var i=0;i<r.length;i++)if(r[i].responseEnd>0)d++;
var k=document.readyState==='loading'?0:1;
var t=Math.min(60,(d/Math.max(4,r.length+2))*46+k*14);
s=Math.min(Math.max(s,t),s+1.6);
c.textContent=('00'+Math.round(s)).slice(-3)+' \\u2014 100';
requestAnimationFrame(f);}
requestAnimationFrame(f);
}catch(e){}})();`,
          }}
        />
      </div>
    </div>
  );
}
